#!/usr/bin/env bash
# SPDX-License-Identifier: Apache-2.0
#
# Renders agent-factory-crds and asserts the contract: the six maku.ogenki.io CRDs, each kept on
# uninstall, each one's spec exactly config/crd's (the one CRD source, generated by controller-gen).
set -euo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/.."
crddir=../../config/crd
fail=0
tmp="$(mktemp -d)"; trap 'rm -rf "$tmp"' EXIT
out="$(helm template af-crds .)"

names="$(yq ea '[select(.kind == "CustomResourceDefinition") | .metadata.name] | sort | join(",")' - <<<"$out")"
want='agentruns.maku.ogenki.io,factories.maku.ogenki.io,mergepolicies.maku.ogenki.io,repositories.maku.ogenki.io,rooms.maku.ogenki.io,tasks.maku.ogenki.io'
[[ $names == "$want" ]] || { echo "FAIL: the chart renders CRDs '$names', want '$want'" >&2; fail=1; }
other="$(yq ea '[select(.kind != null and .kind != "CustomResourceDefinition") | .kind] | join(",")' - <<<"$out")"
[[ -z $other ]] || { echo "FAIL: the chart renders more than CRDs: $other" >&2; fail=1; }

for f in "$crddir"/maku.ogenki.io_*.yaml; do
  name="$(yq '.metadata.name' "$f")"
  crd="$(yq ea "select(.kind == \"CustomResourceDefinition\" and .metadata.name == \"$name\")" - <<<"$out")"
  [[ -n $crd ]] || { echo "FAIL: $name is not rendered" >&2; fail=1; continue; }
  [[ "$(yq '.metadata.annotations."helm.sh/resource-policy"' - <<<"$crd")" == keep ]] || { echo "FAIL: $name lacks helm.sh/resource-policy: keep" >&2; fail=1; }
  [[ "$(yq '.metadata.labels."app.kubernetes.io/part-of"' - <<<"$crd")" == agent-factory ]] || { echo "FAIL: $name lacks app.kubernetes.io/part-of: agent-factory" >&2; fail=1; }
  yq -o json '.spec' "$f" >"$tmp/want.json"
  yq -o json '.spec' - <<<"$crd" >"$tmp/got.json"
  cmp -s "$tmp/want.json" "$tmp/got.json" || { echo "FAIL: $name's spec differs from $f" >&2; fail=1; }
done

# Reusable merge policies, release N: the MergePolicy CRD prints its consumers and keeps the two
# shapes apart (B8, B10).
mp="$(yq ea 'select(.kind == "CustomResourceDefinition" and .metadata.name == "mergepolicies.maku.ogenki.io")' - <<<"$out")"
[[ "$(yq '[.spec.versions[0].additionalPrinterColumns[].name] | contains(["Consumers", "Current"])' - <<<"$mp")" == true ]] || { echo "FAIL: the MergePolicy CRD lacks the Consumers and Current columns" >&2; fail=1; }
[[ "$(yq '[.. | select(has("message")) | .message] | contains(["the per-repository fields (repositoryRef, classes, merge) and the class fields never together (B8)"])' - <<<"$mp")" == true ]] || { echo "FAIL: the MergePolicy CRD lacks the B8 rule" >&2; fail=1; }

# keep: false drops the annotation (uninstalling then deletes every Room and Task)
kept="$(helm template af-crds . --set keep=false | yq ea '[select(.kind == "CustomResourceDefinition") | .metadata.annotations."helm.sh/resource-policy" // ""] | join("")' -)"
[[ -z $kept ]] || { echo "FAIL: keep=false still renders the keep annotation" >&2; fail=1; }

# Exactly the six, and files/ holds nothing else (its glob is `files/*.yaml`). agentgateway's CRDs
# are not this chart's: in a Helm release they push its Secret to the 1 MiB limit (the release stores
# the chart's files and the manifest), so they are applied apart (config/agentgateway, docs/gateway.md).
[[ "$(grep -c '^kind: CustomResourceDefinition$' <<<"$out")" == 6 ]] || { echo "FAIL: the chart renders $(grep -c '^kind: CustomResourceDefinition$' <<<"$out") CRDs, want 6" >&2; fail=1; }
! grep -q 'agentgateway' values.yaml templates/* || { echo "FAIL: the CRD chart still carries agentgateway" >&2; fail=1; }
[[ -z "$(find files -mindepth 1 -not -name 'maku.ogenki.io_*.yaml')" ]] || { echo "FAIL: files/ holds more than the maku.ogenki.io CRDs" >&2; fail=1; }
# the release Secret: Helm stores base64(gzip(release JSON)), and the API refuses a Secret over 1 MiB
size="$(helm install af-crds . --dry-run=client -o json | gzip | base64 -w0 | wc -c)"
(( size < 262144 )) || { echo "FAIL: the release Secret would hold $size bytes; keep it far below 1048576" >&2; fail=1; }
yq -e '(.dependencies // []) | length == 0' Chart.yaml >/dev/null || { echo "FAIL: the CRD chart has a dependency: every install would need to build it" >&2; fail=1; }

# the packaged chart ships the six CRDs, never tests/ (.helmignore)
helm package . -d "$tmp/pkg" >/dev/null
shipped="$(tar -tzf "$tmp"/pkg/agent-factory-crds-*.tgz)"
[[ $(grep -c '^agent-factory-crds/files/maku\.ogenki\.io_.*\.yaml$' <<<"$shipped") == 6 ]] || { echo "FAIL: the package does not ship the six CRDs" >&2; fail=1; }
! grep -q '^agent-factory-crds/tests/' <<<"$shipped" || { echo "FAIL: the package ships tests/" >&2; fail=1; }

[[ $fail == 0 ]] || exit 1
echo "agent-factory-crds render checks passed"
